4	import type { MiaActionHandler } from '@/types/mia';
5	
6	export interface DashboardMiaInterface {
7	  // Filters
8	  setSector: (sector: string) => void;
9	  setPeriod: (period: string) => void;
10	  sector: string;
11	  period: string;
12	}
13	
14	export function useMiaDashboardActions(iface: DashboardMiaInterface): void {
15	  const { setScreenState } = useMia();
16	
17	  const {
18	    setSector,
19	    setPeriod,
20	    sector,
21	    period,
22	  } = iface;
23	
24	  // Sync screen state for MIA context awareness
25	  useEffect(() => {
26	    setScreenState({
27	      active_tab: 'dashboard',
28	      active_filters: {
29	        sector,
30	        period,
31	      },
32	      summary_kpis: {},
33	    });
34	  }, [sector, period, setScreenState]);
35	
36	  // Memoize handlers to avoid re-registration on every render
37	  const handlers = useMemo<Record<string, MiaActionHandler>>(() => ({
38	    dashboard_filter: {
39	      id: 'dashboard_filter',
40	      description: 'Aplicar filtros no dashboard (setor, periodo)',
41	      execute: (data) => {
42	        if (!data) return;
43	        if (data.sector) setSector(data.sector);
44	        if (data.period) setPeriod(data.period);
45	      },
46	    },
47	
48	    dashboard_set_sector: {
49	      id: 'dashboard_set_sector',
50	      description: 'Filtrar dashboard por setor',
51	      execute: (data) => {
52	        if (data?.sector) setSector(data.sector);
53	      },
54	    },
55	
56	    dashboard_set_period: {
57	      id: 'dashboard_set_period',
58	      description: 'Definir periodo de analise do dashboard',
59	      execute: (data) => {
60	        if (data?.period) setPeriod(data.period);
61	      },
62	    },
63	
64	    dashboard_reset_filters: {
65	      id: 'dashboard_reset_filters',
66	      description: 'Resetar filtros do dashboard para padrao',
67	      execute: () => {
68	        setSector('all');
69	        setPeriod('24');
70	      },
71	    },
72	  }), [setSector, setPeriod]);
73	
74	  useMiaActions('/dashboard', handlers);
75	}
