1	/**
2	 * @module PermissionBlur
3	 *
4	 * Componente de proteção visual por permissão.
5	 * Renderiza o conteúdo com blur e overlay de "Acesso Negado" quando
6	 * o usuário não possui permissão para o módulo solicitado.
7	 */
8	
9	import React from 'react';
10	import { AlertTriangle, ArrowLeft } from 'lucide-react';
11	import { Alert, AlertDescription } from '@/shared/ui/alert';
12	import { Button } from '@/shared/ui/button';
13	import { useNavigate } from 'react-router-dom';
14	import { useIsMobile } from '@/shared/hooks/use-mobile';
15	import { usePermissions } from '@/shared/hooks/usePermissions';
16	
17	interface PermissionBlurProps {
18	  children: React.ReactNode;
19	  hasPermission: boolean;
20	  moduleName?: string;
21	  permissionName?: string;
22	  loading?: boolean;
23	}
24	
25	export const PermissionBlur: React.FC<PermissionBlurProps> = ({
26	  children,
27	  hasPermission,
28	  moduleName = 'esta funcionalidade',
29	  permissionName,
30	  loading: loadingProp,
31	}) => {
32	  const navigate = useNavigate();
33	  const isMobile = useIsMobile();
34	  const { loading: permissionsLoading } = usePermissions();
35	
36	  // Enquanto permissões estão carregando, renderizar conteúdo normalmente
37	  // Evita flash de "Acesso Negado" em redes lentas (especialmente mobile)
38	  const isLoading = loadingProp ?? permissionsLoading;
39	  if (isLoading) {
40	    return <>{children}</>;
41	  }
42	
43	  if (!hasPermission) {
44	    return (
45	      <div className="relative min-h-screen">
46	        {/* Conteúdo com blur */}
47	        <div className="filter blur-md pointer-events-none select-none">
48	          {children}
49	        </div>
50	
51	        {/* Overlay com mensagem de acesso negado */}
52	        <div className="absolute inset-0 bg-black/20 flex items-center justify-center z-50">
53	          {isMobile && (
54	            <Button
55	              variant="ghost"
56	              size="icon"
57	              onClick={() => navigate('/dashboard')}
58	              className="absolute top-4 left-4 h-10 w-10 rounded-full bg-white/80 text-foreground shadow-sm"
59	              aria-label="Voltar para início"
60	            >
61	              <ArrowLeft className="h-5 w-5" />
62	            </Button>
63	          )}
64	          <div className="bg-white dark:bg-gray-800 p-8 rounded-lg shadow-2xl max-w-md mx-4 text-center">
65	            <div className="flex justify-center mb-4">
66	              <AlertTriangle className="h-16 w-16 text-red-500" />
67	            </div>
68	
69	            <h2 className="text-2xl font-bold text-gray-900 dark:text-white mb-4">
70	              Acesso Negado
71	            </h2>
72	
73	            <Alert className="mb-6 border-red-200 bg-red-50 dark:bg-red-900/20">
74	              <AlertTriangle className="h-4 w-4 text-red-600" />
75	              <AlertDescription className="text-red-800 dark:text-red-200">
76	                Você não tem acesso ao módulo {moduleName} para acessar isso.
77	                {permissionName && (
78	                  <span className="block mt-2 text-sm">
79	                    Permissão necessária:{' '}
80	                    <code className="bg-red-100 dark:bg-red-800 px-1 py-0.5 rounded text-xs">
81	                      {permissionName}
82	                    </code>
83	                  </span>
84	                )}
85	              </AlertDescription>
86	            </Alert>
87	
88	            <div className="space-y-3">
89	              <p className="text-gray-600 dark:text-gray-300 text-sm">
90	                Entre em contato com o administrador do sistema para solicitar
